export const BASE = "68a303312a393191f714b465232bf25dc4707876";
export const sources = {
  "src/components/AdvancedWorkspace/ExampleDialog.jsx": "import { presentStoredError } from '../../i18n/userMessage.js';\nimport { useEffect, useRef, useState } from 'react';\n\nimport { AdvancedDialog } from './AdvancedDialog.jsx';\nimport { useProjectContext } from '../../store/ProjectContext';\nimport { batchTitleVoice, isTtsAvailable } from '../../store/xttsSettings.js';\nimport { exampleMediaPlan } from '../../store/advancedExamples/media.js';\nimport { Button } from '../common/Button';\nimport { Toggle } from '../common/Toggle';\nimport './Examples.css';\n\nexport function ExampleDialog({ state, replacesInitialRoot, disabled, onCancel, onConfirm, onStop }) {\n  const { xttsSettings } = useProjectContext();\n  const [images, setImages] = useState(true);\n  const audioAvailable = isTtsAvailable(xttsSettings) && !!batchTitleVoice(xttsSettings);\n  const [audios, setAudios] = useState(audioAvailable);\n  const plan = exampleMediaPlan(state.example);\n  const created = state.inserted;\n  // « Arrêter les médias » disparaît avec la génération : le focus passe à\n  // « Fermer », redevenu actif, au lieu de tomber sur la page.\n  const closeRef = useRef(null);\n  useEffect(() => {\n    if (state.stopped && !state.busy) closeRef.current?.focus();\n  }, [state.stopped, state.busy]);\n  return (\n    <AdvancedDialog\n      title={state.example.title}\n      description={state.example.description}\n      onCancel={onCancel} onConfirm={created ? null : () => onConfirm({ images, audios })}\n      confirmLabel={replacesInitialRoot ? 'Créer cet exemple' : 'Ajouter cet exemple'}\n      cancelLabel={created ? 'Fermer' : 'Annuler'}\n      confirmDisabled={disabled || (audios && !audioAvailable)} busy={state.busy}\n      cancelRef={closeRef}\n      footer={state.busy && created ? (\n        // Seule la génération des médias s'arrête : le graphe est déjà inséré.\n        <Button onClick={onStop}>Arrêter les médias</Button>\n      ) : null}\n    >\n      {!created && (\n        <>\n          <p className=\"advanced-example-explanation\">\n            {replacesInitialRoot\n              ? 'Cet exemple remplace l’Écran d’entrée vide et devient ton pack. Tu peux ensuite tout modifier.'\n              : 'Cet exemple s’ajoute à côté de ton graphe. Son point de départ sera sélectionné ; tu peux l’écouter depuis cet Écran, puis le raccorder à ton parcours.'}\n          </p>\n          <fieldset className=\"advanced-example-media\" disabled={state.busy}>\n            <legend>Créer les médias à partir des noms des Écrans</legend>\n            <label className=\"advanced-example-toggle\">\n              <span>Images-titres <small>{plan.images.length} images avec le texte du nom</small></span>\n              <Toggle on={images} onChange={setImages} ariaLabel=\"Générer les images-titres de cet exemple\" />\n            </label>\n            <label className=\"advanced-example-toggle\">\n              <span>Audios TTS <small>{plan.audios.length} noms prononcés · {xttsSettings?.backend === 'xtts' ? 'XTTS' : 'Piper'}</small></span>\n              <Toggle on={audios} onChange={setAudios} disabled={!audioAvailable} ariaLabel=\"Générer les audios de cet exemple\" />\n            </label>\n            {!audioAvailable && <p className=\"advanced-example-explanation\">Choisis une voix TTS dans les Préférences pour générer les audios.</p>}\n          </fieldset>\n          <p className=\"advanced-example-explanation\">\n            {plan.withoutImage} Écrans restent sans image et {plan.withoutAudio} sans audio, comme prévu dans cet exemple.\n            {' '}Les textes racontent le parcours ; les listes de choix ne portent aucun média.\n          </p>\n        </>\n      )}\n      {state.progress && (\n        <div className=\"advanced-example-progress\" role=\"status\" aria-live=\"polite\">\n          {state.progress.total > 0 && <progress max={state.progress.total} value={state.progress.completed} />}\n          <span>{state.progress.label || 'Préparation des médias…'}</span>\n        </div>\n      )}\n      {state.result && (\n        <div className=\"advanced-example-explanation\" role=\"status\">\n          <p>L’exemple est {state.report.replacedInitialRoot ? 'créé' : 'ajouté'} : {state.example.stages.length} Écrans et {state.example.actions.length} listes de choix.</p>\n          <p>{state.result.imageCount} images créées · {state.result.audioCount} audios ajoutés à la file TTS.</p>\n          {state.result.audioCount > 0 && <p>Les audios se rattachent à leurs Écrans au fur et à mesure. Leur progression et les éventuelles erreurs sont visibles dans la file IA.</p>}\n        </div>\n      )}\n      {state.stopped && (\n        <p className=\"advanced-example-explanation\" role=\"status\">\n          Génération des médias arrêtée. Le graphe reste en place avec les médias déjà affectés ;\n          {' '}les audios déjà envoyés restent visibles dans la file IA.\n        </p>\n      )}\n      {state.error && <p className=\"advanced-example-error\" role=\"alert\">{state.error}</p>}\n      {state.result?.errors.length > 0 && (\n        <div className=\"advanced-example-error\" role=\"alert\">\n          <p>L’exemple est conservé. Certains médias n’ont pas pu être préparés :</p>\n          <ul>{state.result.errors.map((error, rank) => <li key={rank}>{presentStoredError(error)}</li>)}</ul>\n        </div>\n      )}\n    </AdvancedDialog>\n  );\n}\n",
  "src/components/AdvancedWorkspace/ExamplesMenu.jsx": "import { useEffect, useRef, useState } from 'react';\n\nimport { ChevronDown } from '../icons/LucideLocal';\nimport { ADVANCED_EXAMPLES, createAdvancedExample } from '../../store/advancedExamples/catalog.js';\nimport './Examples.css';\n\nexport function ExamplesMenu({ disabled, disabledReason, onChoose }) {\n  const [open, setOpen] = useState(false);\n  const container = useRef(null);\n  const trigger = useRef(null);\n  useEffect(() => {\n    if (!open) return undefined;\n    const dismiss = (event) => {\n      if (!container.current?.contains(event.target)) setOpen(false);\n    };\n    const escape = (event) => {\n      if (event.key === 'Escape') {\n        event.stopPropagation();\n        setOpen(false);\n        trigger.current?.focus();\n      }\n    };\n    document.addEventListener('pointerdown', dismiss);\n    document.addEventListener('keydown', escape, true);\n    container.current?.querySelector('[role=\"menuitem\"]')?.focus();\n    return () => {\n      document.removeEventListener('pointerdown', dismiss);\n      document.removeEventListener('keydown', escape, true);\n    };\n  }, [open]);\n\n  function navigate(event) {\n    event.stopPropagation();\n    const buttons = [...container.current.querySelectorAll('[role=\"menuitem\"]')];\n    const rank = buttons.indexOf(document.activeElement);\n    if (event.key === 'ArrowDown' || event.key === 'ArrowUp') {\n      event.preventDefault();\n      buttons[(rank + (event.key === 'ArrowDown' ? 1 : -1) + buttons.length) % buttons.length]?.focus();\n    } else if (event.key === 'Home' || event.key === 'End') {\n      event.preventDefault();\n      buttons[event.key === 'Home' ? 0 : buttons.length - 1]?.focus();\n    } else if (event.key === 'Tab') setOpen(false);\n  }\n\n  return (\n    <div className=\"advanced-examples-menu\" ref={container}>\n      <button\n        ref={trigger} type=\"button\" className=\"advanced-create-command advanced-examples-trigger\"\n        disabled={disabled} title={disabled ? disabledReason : 'Ajouter un exemple de quiz ou d’histoire à choix'}\n        aria-haspopup=\"menu\" aria-expanded={open && !disabled}\n        onClick={() => setOpen(!open)}\n        onKeyDown={(event) => {\n          if (event.key === 'ArrowDown') { event.preventDefault(); event.stopPropagation(); setOpen(true); }\n        }}\n      >\n        Exemples <ChevronDown className=\"chrome-icon\" aria-hidden=\"true\" />\n      </button>\n      {open && !disabled && (\n        <div className=\"advanced-examples-list\" role=\"menu\" aria-label=\"Exemples de graphes\" onKeyDown={navigate}>\n          {ADVANCED_EXAMPLES.map((example) => (\n            <button key={example.id} type=\"button\" role=\"menuitem\" className=\"advanced-examples-item\" onClick={() => {\n              setOpen(false);\n              onChoose(createAdvancedExample(example.id));\n            }}>\n              <strong>{example.title}</strong>\n              <span>{example.description}</span>\n              <small>{example.stageCount} Écrans · {example.actionCount} listes de choix</small>\n            </button>\n          ))}\n        </div>\n      )}\n    </div>\n  );\n}\n",
  "src/hooks/useAdvancedExamples.js": "import { useMessageLanguage } from '../i18n/useMessageLanguage.js';\nimport { presentStoredError } from '../i18n/userMessage.js';\nimport { aiRef } from '../i18n/aiPresentation.js';\nimport { useEffect, useRef, useState } from 'react';\nimport { remove } from '@tauri-apps/plugin-fs';\n\nimport { useProjectContext } from '../store/ProjectContext';\nimport { batchTitleVoice, isTtsAvailable } from '../store/xttsSettings.js';\nimport { exampleMediaPlan, generateExampleMedia } from '../store/advancedExamples/media.js';\nimport { createExampleHistory } from '../store/advancedExamples/exampleHistory.js';\nimport { generateTextImage } from '../components/TextImageGenerator/generateTextImage';\nimport { generateUuid } from '../utils/uuid.js';\n\n// Le projet reçoit d'abord le motif atomique, puis uniquement les médias\n// prévus. Les TTS restent dans la file commune et s'appliquent par UUID/époque.\n//\n// Historique : les médias se fondent dans l'étape d'insertion tant que\n// l'auteur n'a rien fait d'autre ; sinon chacun devient une étape ordinaire\n// (règle détaillée dans `advancedExamples/exampleHistory.js`).\n//\n// Arrêt : `stop` invalide la boucle des médias par la même garde que le\n// changement de projet. Le graphe inséré reste en place, l'image en cours de\n// fabrication est jetée, et les audios déjà confiés à la file IA y restent\n// (annulables depuis cette file).\nexport function useAdvancedExamples({ authoring, projectEpoch, onAssignMedia, onInserted }) {\n  const context = useProjectContext();\n  const latest = useRef(null);\n  latest.current = { authoring, projectEpoch, onAssignMedia, onInserted, context };\n  const mounted = useRef(true);\n  useMessageLanguage();\n  const [state, setState] = useState(null);\n  const activeRef = useRef(null);\n  const historyRef = useRef(null);\n  historyRef.current ??= createExampleHistory();\n  useEffect(() => {\n    mounted.current = true;\n    return () => { mounted.current = false; };\n  }, []);\n  useEffect(() => {\n    activeRef.current = null;\n    historyRef.current.release();\n    setState(null);\n  }, [projectEpoch]);\n\n  function open(example) {\n    if (activeRef.current?.busy) return;\n    const draft = { example, busy: false, inserted: false, stopped: false, result: null, error: '', progress: null };\n    activeRef.current = draft;\n    setState(draft);\n  }\n\n  function close() {\n    if (activeRef.current?.busy) return;\n    activeRef.current = null;\n    setState(null);\n  }\n\n  // Seule la phase des médias est interruptible : l'insertion du graphe est\n  // un geste unique, déjà atomique.\n  function stop() {\n    const draft = activeRef.current;\n    if (!draft?.busy || !draft.inserted || draft.stopped) return;\n    Object.assign(draft, { stopped: true, busy: false, progress: null });\n    setState({ ...draft });\n  }\n\n  async function confirm({ images, audios, anchor }) {\n    const draft = activeRef.current;\n    if (!draft || draft.busy || draft.inserted) return;\n    const epoch = latest.current.projectEpoch;\n    const captured = latest.current.context;\n    const voice = batchTitleVoice(captured.xttsSettings);\n    const current = () => mounted.current && latest.current.projectEpoch === epoch\n      && activeRef.current === draft && !draft.stopped;\n    const update = (patch) => {\n      if (!current()) return;\n      Object.assign(draft, patch);\n      setState({ ...draft });\n    };\n    if (audios && (!isTtsAvailable(captured.xttsSettings) || !voice)) {\n      update({ error: 'Choisis une voix TTS dans les Préférences, ou crée cet exemple sans audio.' });\n      return;\n    }\n    update({ busy: true, error: '', progress: { completed: 0, total: 0, label: 'Création du graphe…' } });\n    try {\n      let committed = null;\n      const outcome = await latest.current.authoring.runExample(draft.example, {\n        anchor, onCommitted: (commit) => { committed = commit; },\n      });\n      if (!current()) return;\n      if (outcome.status !== 'applied') {\n        update({ error: outcome.error || 'L’exemple n’a pas été ajouté. Termine le geste en cours puis réessaie.' });\n        return;\n      }\n      const report = outcome.report.example;\n      const exampleHistory = historyRef.current;\n      // Sans repère de commit, aucun média ne sera fondu : étapes ordinaires.\n      const history = committed ? exampleHistory.historyFor(exampleHistory.claim(committed)) : true;\n      update({ inserted: true, report });\n      latest.current.onInserted?.({ ...report, projectEpoch: epoch });\n      const plan = exampleMediaPlan(draft.example, report.stages);\n      const result = await generateExampleMedia({\n        plan, images, audios, isCurrent: current,\n        onProgress: (progress) => update({ progress }),\n        generateImage: (text) => generateTextImage(text, captured.workspaceDir, {\n          filename: `exemple-${generateUuid()}.png`,\n          mediaStorage: captured.mediaStorage,\n        }),\n        discardImage: (path) => remove(path),\n        assignImage: async (uuid, path) => {\n          if (!current()) return null;\n          const assigned = await latest.current.onAssignMedia(uuid, 'image', path, { projectEpoch: epoch, history });\n          // Une image affectée juste avant l'arrêt reste dans le document : elle\n          // est donc déclarée, tant que le projet est encore celui de l'exemple.\n          if (assigned?.status === 'applied' && latest.current.projectEpoch === epoch) {\n            // L'image est déjà référencée : un échec de la déclaration ne doit\n            // pas la faire passer pour non affectée, donc supprimée.\n            try {\n              captured.onMediaCreated?.(path);\n            } catch {\n              // Déclaration accessoire : l'image reste affectée dans le document.\n            }\n          }\n          return assigned;\n        },\n        queueAudio: ({ stageUuid, text }) => captured.onQueueXttsGenerate({\n          target: {\n            kind: 'advancedStage', projectEpoch: epoch,\n            apply: (path) => latest.current.projectEpoch === epoch\n              ? latest.current.onAssignMedia(stageUuid, 'audio', path, { projectEpoch: epoch, history })\n              : null,\n          },\n          targetLabelRef: aiRef('ai:queue.example.target', { name: text }), voiceLabel: voice,\n          request: {\n            text, language: captured.xttsSettings?.language || 'fr',\n            speaker: null, voice, savePath: captured.savePath,\n            filenameHint: `exemple-${stageUuid}`,\n          },\n        }),\n      });\n      if (!current() || result.stale) return;\n      update({ result, progress: null });\n    } catch (error) {\n      update({ error });\n    } finally {\n      update({ busy: false });\n    }\n  }\n\n  return { state: state ? { ...state, error: presentStoredError(state.error) } : null, open, close, stop, confirm };\n}\n",
  "src/store/advancedExamples/catalog.js": "import { gardenQuiz, castleQuiz } from './quizExamples.js';\nimport { greyRabbitStory, lighthouseStory } from './storyExamples.js';\nimport { explorerTrain } from './trainExample.js';\n\nconst FACTORIES = Object.freeze({\n  'garden-quiz': gardenQuiz,\n  'castle-quiz': castleQuiz,\n  'grey-rabbit': greyRabbitStory,\n  lighthouse: lighthouseStory,\n  'explorer-train': explorerTrain,\n});\n\n// Les factories rendent à chaque appel de nouveaux tableaux : une génération\n// de médias ou un déplacement ne peut modifier l'exemple suivant.\nexport function createAdvancedExample(id) {\n  if (!Object.hasOwn(FACTORIES, id)) throw new RangeError(`Exemple de graphe inconnu : ${id}`);\n  const factory = FACTORIES[id];\n  if (typeof factory !== 'function') throw new RangeError(`Exemple de graphe inconnu : ${id}`);\n  return factory();\n}\n\nexport const ADVANCED_EXAMPLES = Object.freeze(Object.keys(FACTORIES).map((id) => {\n  const example = createAdvancedExample(id);\n  return Object.freeze({ id, title: example.title, description: example.description,\n    stageCount: example.stages.length, actionCount: example.actions.length });\n}));\n",
  "src/store/advancedExamples/exampleBuilder.js": "// Descriptions autonomes du catalogue : les rangs sont locaux au motif collé.\n// Les intentions médias restent distinctes des références, absentes avant génération.\nexport function exampleBuilder(id, title, description) {\n  const stages = [];\n  const actions = [];\n  const transitions = [];\n  // `role` ne fait que choisir les boutons par défaut : il n'est pas conservé\n  // dans la description, que rien ne relit au-delà de ce choix.\n  function stage(name, x, y, { role = 'narration', image = false, audio = true, controls = {} } = {}) {\n    if (role === 'choice' && !audio) throw new Error('Un choix de menu doit pouvoir être écouté.');\n    const rank = stages.length;\n    const spoken = audio && role === 'narration';\n    stages.push({\n      name, offset: { x, y }, image: null, audio: null,\n      mediaIntent: { image, audio },\n      controls: { wheel: role === 'choice', ok: true, home: role !== 'entry', pause: spoken, autoplay: spoken, ...controls },\n    });\n    return rank;\n  }\n  function action(name, targets, x, y) {\n    const rank = actions.length;\n    actions.push({ name, options: targets.map((target) => ({ target: 'stage', stage: target })), offset: { x, y } });\n    return rank;\n  }\n  function transition(from, to, optionIndex = 0, slot = 'ok') {\n    transitions.push({ stage: from, slot, action: to, optionIndex });\n  }\n  function link(from, target, name, x, y) {\n    const rank = action(name, [target], x, y);\n    transition(from, rank);\n    return rank;\n  }\n  function finish(hub, returnAction) {\n    // Le hub n'est pas l'entrée : aucun retour ne transforme squareOne en option.\n    // Son Accueil reste sans destination, pour ne jamais retomber sur lui-même.\n    for (let rank = 0; rank < stages.length; rank += 1) {\n      if (rank !== 0 && rank !== hub) transition(rank, returnAction, 0, 'home');\n    }\n    return { id, title, description, entryRank: 0, stages, actions, transitions };\n  }\n  return { stage, action, transition, link, finish, stages, actions };\n}\n\nexport function opening(builder, title, menuText, bottom, { introText } = {}) {\n  const entry = builder.stage(title, 0, 0, { role: 'entry', image: true });\n  const hub = builder.stage(menuText, 640, 0);\n  if (introText) {\n    const intro = builder.stage(introText, 320, -360);\n    builder.link(entry, intro, 'Commencer le parcours', 160, -180);\n    builder.link(intro, hub, 'Ouvrir le menu', 480, -180);\n  } else {\n    builder.link(entry, hub, 'Ouvrir le menu', 320, 0);\n  }\n  const returnAction = builder.action('Retour au menu', [hub], 640, bottom);\n  return { entry, hub, returnAction };\n}\n",
  "src/store/advancedExamples/media.js": "// Les noms sont le contenu des exemples ; les intentions de médias sont\n// distinctes des emplacements vides du document avant génération.\nexport function exampleMediaPlan(example, stageUuids = []) {\n  const images = [];\n  const audios = [];\n  for (const [rank, stage] of example.stages.entries()) {\n    const image = stage.mediaIntent?.image === true;\n    const audio = stage.mediaIntent?.audio === true;\n    if (!image && !audio) continue;\n    const text = typeof stage.name === 'string' ? stage.name.trim() : '';\n    // Ne jamais laisser le générateur d'image retomber sur « Sans titre »,\n    // ni substituer l'identifiant technique au texte à prononcer.\n    if (!text) throw new TypeError('Un Écran avec média doit avoir un texte.');\n    const target = { rank, text, stageUuid: stageUuids[rank] ?? null };\n    if (image) images.push(target);\n    if (audio) audios.push(target);\n  }\n  return {\n    images, audios,\n    withoutImage: example.stages.length - images.length,\n    withoutAudio: example.stages.length - audios.length,\n  };\n}\n\n// Génération injectée, éprouvée sans navigateur ni TTS. Les erreurs partielles\n// gardent la structure créée et les fichiers déjà affectés ; une seule erreur\n// n'empêche pas les autres Écrans de recevoir leur média.\n//\n// `isCurrent` devient faux au changement de projet comme à l'arrêt demandé par\n// l'auteur : la boucle s'interrompt au prochain point de contrôle, sans rien\n// affecter ni mettre en file de plus. Une image écrite mais non affectée —\n// projet changé, arrêt, refus du geste — est rendue à `discardImage` : aucun\n// fichier orphelin ne reste dans l'espace de travail.\nexport async function generateExampleMedia({\n  plan, images, audios, generateImage, assignImage, queueAudio,\n  isCurrent, onProgress = () => {}, discardImage = async () => {},\n}) {\n  const errors = [];\n  let imageCount = 0;\n  let audioCount = 0;\n  const total = (images ? plan.images.length : 0) + (audios ? plan.audios.length : 0);\n  let completed = 0;\n  const progress = (label) => onProgress({ completed, total, label });\n  const active = () => isCurrent();\n  for (const target of images ? plan.images : []) {\n    if (!active()) return { stale: true, errors, imageCount, audioCount };\n    progress(`Image : ${target.text}`);\n    let path = null;\n    // Tant que l'image n'est pas affectée, elle reste à jeter.\n    const discard = async () => {\n      const pending = path;\n      path = null;\n      if (!pending) return;\n      try {\n        await discardImage(pending);\n      } catch {\n        // Le nettoyage est au mieux : son échec ne masque pas l'issue réelle.\n      }\n    };\n    try {\n      path = await generateImage(target.text, target);\n      if (!active()) {\n        await discard();\n        return { stale: true, errors, imageCount, audioCount };\n      }\n      if (!path) throw new Error('Aucun fichier image produit.');\n      const outcome = await assignImage(target.stageUuid, path);\n      if (outcome?.status === 'applied') {\n        path = null;\n        imageCount += 1;\n      } else await discard();\n      if (!active()) return { stale: true, errors, imageCount, audioCount };\n      if (outcome?.status !== 'applied') throw new Error('L’Écran ne peut plus recevoir cette image.');\n    } catch (error) {\n      await discard();\n      errors.push({ userMessage: error, prefix: `${target.text} : ` });\n    }\n    completed += 1;\n    progress('');\n  }\n  for (const target of audios ? plan.audios : []) {\n    if (!active()) return { stale: true, errors, imageCount, audioCount };\n    progress(`Audio : ${target.text}`);\n    try {\n      await queueAudio(target);\n      audioCount += 1;\n    } catch (error) {\n      errors.push({ userMessage: error, prefix: `${target.text} : ` });\n    }\n    completed += 1;\n    progress('');\n  }\n  return { stale: !active(), errors, imageCount, audioCount };\n}\n",
  "src/store/advancedExamples/quizExamples.js": "import { exampleBuilder, opening } from './exampleBuilder.js';\n\nconst GARDEN_QUESTIONS = [\n  {\n    subject: 'les galeries',\n    topic: 'Sous la terre.',\n    question: 'Une petite butte est apparue dans le potager. Qui creuse des galeries sous le jardin ?',\n    answers: ['La taupe.', 'Le papillon.', 'Le merle.'],\n    feedback: [\n      'Bravo ! La taupe creuse la terre avec ses larges pattes. Tourne la roue pour choisir un autre sujet.',\n      'Le papillon vole de fleur en fleur. Notre animal creuse sous terre. Écoute à nouveau la question.',\n      'Le merle cherche sa nourriture à la surface du sol. Notre animal creuse des tunnels. Réessaie !',\n    ],\n  },\n  {\n    subject: 'la promenade nocturne',\n    topic: 'À la tombée du jour.',\n    question: 'Ça remue près de la haie ! Quel animal couvert de piquants cherche sa nourriture dans le jardin la nuit ?',\n    answers: ['Le rouge-gorge.', 'Le hérisson.', 'La libellule.'],\n    feedback: [\n      'Le rouge-gorge a des plumes, pas des piquants. Écoute bien l’indice et essaie une autre réponse.',\n      'Bravo ! Le hérisson sort surtout la nuit pour chercher à manger. La roue des sujets t’attend.',\n      'La libellule a des ailes et vole surtout le jour. Cherche plutôt un promeneur à piquants. Réessaie !',\n    ], correct: 1,\n  },\n  {\n    subject: 'la coquille',\n    topic: 'Après la pluie.',\n    question: 'Après l’averse, une trace brillante traverse l’allée. Qui se promène avec une coquille sur le dos ?',\n    answers: ['La fourmi.', 'La limace.', 'L’escargot.'],\n    feedback: [\n      'La fourmi rejoint sa fourmilière sans coquille sur le dos. Cherche le petit animal à coquille. Réessaie !',\n      'La limace laisse aussi une trace brillante, mais n’a pas de coquille sur le dos. Écoute à nouveau la question.',\n      'Bravo ! L’escargot peut se réfugier dans sa coquille. Tourne la roue pour choisir un autre sujet.',\n    ], correct: 2,\n  },\n  {\n    subject: 'le pollen',\n    topic: 'De fleur en fleur.',\n    question: 'Une fleur se balance, puis une autre. Qui transporte le pollen en butinant les fleurs du jardin ?',\n    answers: ['L’abeille.', 'Le crapaud.', 'Le ver de terre.'],\n    feedback: [\n      'Bravo ! Du pollen s’accroche à l’abeille et voyage de fleur en fleur. La roue des sujets t’attend.',\n      'Le crapaud chasse au sol ; il ne butine pas les fleurs. Cherche un visiteur qui vole. Réessaie !',\n      'Le ver de terre se déplace dans la terre ; il ne butine pas. Écoute la question et essaie une autre réponse.',\n    ],\n  },\n];\n\nconst CASTLE_QUESTIONS = [\n  {\n    subject: 'la forge',\n    topic: 'Chez le forgeron.',\n    question: 'Ting, ting ! Le forgeron pose du fer chaud sur son enclume. Quel outil utilise-t-il pour lui donner sa forme ?',\n    answers: ['Le marteau.', 'Le pinceau.', 'La louche.'],\n    feedback: [\n      'Bravo ! Le forgeron frappe le fer avec son marteau pour le façonner. Tourne la roue pour visiter un autre métier.',\n      'Le pinceau sert à peindre. Ici, il faut un outil qui frappe le fer. Écoute à nouveau la question.',\n      'La louche sert à verser la soupe. Cherche plutôt l’outil qui frappe sur l’enclume. Réessaie !',\n    ],\n  },\n  {\n    subject: 'la pâte à pain',\n    topic: 'Chez le boulanger.',\n    question: 'Le boulanger laisse reposer sa pâte sous un torchon. Quel ingrédient va l’aider à gonfler ?',\n    answers: ['Le sable.', 'La levure.', 'Le poivre.'],\n    feedback: [\n      'Le sable ne va pas dans le pain. Cherche l’ingrédient qui fait gonfler la pâte. Réessaie !',\n      'Bravo ! La levure produit de petites bulles qui font gonfler la pâte. La roue des métiers t’attend.',\n      'Le poivre apporte du goût, mais ne fait pas gonfler la pâte. Écoute à nouveau la question.',\n    ], correct: 1,\n  },\n  {\n    subject: 'les semis',\n    topic: 'Chez le jardinier.',\n    question: 'Le jardinier vient de semer dans une terre sèche. Que doit-il apporter aux graines pour les aider à germer ?',\n    answers: ['Une cloche.', 'Une plume.', 'De l’eau.'],\n    feedback: [\n      'La cloche sonne, mais la terre reste sèche. De quoi les graines ont-elles besoin ? Réessaie !',\n      'La plume n’humidifie pas la terre. Cherche ce qui aidera les graines à germer. Écoute à nouveau la question.',\n      'Bravo ! L’eau permet aux graines de commencer à germer. Tourne la roue pour visiter un autre métier.',\n    ], correct: 2,\n  },\n  {\n    subject: 'le courrier',\n    topic: 'Chez le messager.',\n    question: 'Le messager prépare son départ pour le château voisin. Que va-t-il emporter pour transmettre des nouvelles écrites ?',\n    answers: ['Une lettre.', 'Une brique.', 'Un balai.'],\n    feedback: [\n      'Bravo ! La lettre contient les nouvelles que le messager doit porter. La roue des métiers t’attend.',\n      'La brique sert à construire. Cherche l’objet qui contient un message écrit. Réessaie !',\n      'Le balai sert à nettoyer. Le messager cherche des nouvelles à porter, pas du ménage à faire. Réessaie !',\n    ],\n  },\n  {\n    subject: 'la charpente',\n    topic: 'Chez le charpentier.',\n    question: 'Le charpentier prépare les grandes poutres qui soutiendront le toit. Quelle matière utilise-t-il ?',\n    answers: ['La laine.', 'Le bois.', 'Le beurre.'],\n    feedback: [\n      'La laine est souple et sert à fabriquer des vêtements. Cherche une matière solide pour les poutres. Réessaie !',\n      'Bravo ! Le charpentier taille et assemble des poutres de bois. Tourne la roue pour visiter un autre métier.',\n      'Le beurre est bien trop mou pour soutenir un toit. Écoute à nouveau la question et choisis une autre matière.',\n    ], correct: 1,\n  },\n  {\n    subject: 'le vase',\n    topic: 'Chez le potier.',\n    question: 'Sous les mains du potier, une boule souple devient un vase. Quelle matière modèle-t-il avant de la cuire ?',\n    answers: ['La glace.', 'Les feuilles.', 'L’argile.'],\n    feedback: [\n      'La glace fond quand on la chauffe. Le potier cherche une matière qui durcit à la cuisson. Réessaie !',\n      'Les feuilles ne forment pas une pâte à modeler pour ce vase. Écoute à nouveau la question.',\n      'Bravo ! Le potier modèle l’argile, puis la cuisson la rend solide. La roue des métiers t’attend.',\n    ], correct: 2,\n  },\n];\n\nfunction quiz(id, title, description, questions, { entryText, menuText, introText, farewellText }) {\n  const b = exampleBuilder(id, title, description);\n  const bottom = questions.length * 1100 + 360;\n  const { hub, returnAction } = opening(b, entryText, menuText, bottom, { introText });\n  const topics = [];\n  const completed = [];\n  questions.forEach((q, index) => {\n    const y = 360 + index * 1100;\n    const topic = b.stage(q.topic, 1280, y, { role: 'choice', image: true });\n    const prompt = b.stage(q.question, 1920, y);\n    topics.push(topic);\n    b.link(topic, prompt, `Écouter la question — ${q.subject}`, 1600, y);\n    const choices = [];\n    const results = [];\n    for (let answer = 0; answer < q.answers.length; answer += 1) {\n      const lane = y + (answer - 1) * 280;\n      const choice = b.stage(q.answers[answer], 3200, lane, { role: 'choice', image: true });\n      const result = b.stage(q.feedback[answer], 3840, lane);\n      choices.push(choice);\n      results.push(result);\n      b.link(choice, result, `Vérifier ${q.answers[answer]} — ${q.subject}`, 3520, lane);\n    }\n    const choose = b.action(`Réponses — ${q.subject}`, choices, 2560, y);\n    const retry = b.action(`Réécouter la question — ${q.subject}`, [prompt], 4160, y);\n    b.transition(prompt, choose);\n    results.forEach((result, rank) => {\n      if (rank === (q.correct ?? 0)) completed.push(result);\n      else b.transition(result, retry);\n    });\n  });\n  const exit = b.stage('Terminer le quiz.', 1280, bottom - 280, { role: 'choice', image: true });\n  const farewell = b.stage(farewellText, 1920, bottom - 280, { image: true, controls: { autoplay: false } });\n  b.link(exit, farewell, 'Terminer ce tour du quiz', 1600, bottom - 280);\n  const menu = b.action('Choisir un sujet du quiz ou terminer', [...topics, exit], 960, 0);\n  b.transition(hub, menu);\n  completed.forEach((result) => b.transition(result, menu));\n  b.transition(farewell, returnAction);\n  return b.finish(hub, returnAction);\n}\n\nexport function gardenQuiz() {\n  return quiz('garden-quiz', 'Quiz — Animaux du jardin',\n    'Quatre rencontres au jardin, trois réponses par question et des indices pour réessayer à son rythme.', GARDEN_QUESTIONS, {\n      entryText: 'Le quiz des animaux du jardin.',\n      menuText: 'Quel animal du jardin veux-tu découvrir ? Choisis un sujet avec la roue.',\n      introText: 'Pousse la porte du jardin ! Choisis un sujet avec la roue et OK, puis réponds à la question. Si tu te trompes, tu peux réessayer.',\n      farewellText: 'Les habitants du jardin te saluent. Appuie sur OK pour retrouver les sujets du quiz.',\n    });\n}\n\nexport function castleQuiz() {\n  return quiz('castle-quiz', 'Quiz — Métiers du château',\n    'Six ateliers à visiter, trois réponses par question et des artisans qui donnent des indices pour réessayer.', CASTLE_QUESTIONS, {\n      entryText: 'Le quiz des métiers du château.',\n      menuText: 'Quel atelier du château veux-tu visiter ? Choisis un métier avec la roue.',\n      introText: 'Bienvenue au château ! Avec la roue et OK, choisis un métier, puis une réponse. Les artisans te donnent un indice si tu te trompes.',\n      farewellText: 'Les artisans te saluent depuis leurs ateliers. Appuie sur OK pour retrouver la roue des métiers.',\n    });\n}\n",
  "src/store/advancedExamples/storyExamples.js": "import { exampleBuilder, opening } from './exampleBuilder.js';\n\nconst RABBIT_TRAILS = [\n  {\n    label: 'du potager', title: 'Explorer le potager.',\n    scene: 'Pico a traversé le potager ce matin. Dans la boue, des petites pattes et des palmes partent dans deux directions.',\n    choices: ['Suivre les petites pattes.', 'Suivre les palmes.'],\n    outcomes: [\n      'Les petits pas mènent au chêne de Zoé. Une plume noire flotte sur une branche. La pie vous appelle.',\n      'Les palmes mènent à Gustave le canard. Il n’a rien vu. Pico revient au potager : « Essayons l’autre piste. »',\n    ],\n    clue: 'Zoé a vu Nino, le meunier, ramasser un objet brillant. Il est rentré au moulin. Pico bondit : « Allons le voir ! »',\n  },\n  {\n    label: 'de la pie', title: 'Questionner Zoé la pie.',\n    scene: 'Zoé surveillait le jardin depuis son chêne. Elle a vu un éclat près du pont, puis Gustave se poser sur la mare.',\n    choices: ['Parler de l’objet brillant.', 'Parler du canard.'],\n    outcomes: [\n      '« Nino, le meunier, tenait quelque chose qui tintait », raconte Zoé. Il rentrait au moulin, son panier sous le bras.',\n      '« Gustave ? Il dormait près de la mare ! » Zoé n’a rien vu autour de lui. Il vaut mieux parler de ce qui brillait.',\n    ],\n    clue: 'Pico reconnaît le tintement de sa clochette. Nino l’a peut-être mise à l’abri dans son moulin. Vous prenez le chemin.',\n  },\n  {\n    label: 'du pont', title: 'Chercher près du pont.',\n    scene: 'Pico s’était arrêté sur ce pont. Un éclat brille dans la rivière ; quelque chose de bleu dépasse sur la berge.',\n    choices: ['Examiner l’éclat dans l’eau.', 'Examiner le ruban bleu.'],\n    outcomes: [\n      'Léa la loutre plonge jusqu’à l’éclat. C’est un caillou de quartz ! Pico revient sur la berge pour chercher encore.',\n      'C’est le ruban du collier de Pico. Léa vous rejoint : « Nino, le meunier, a trouvé une clochette ici, tout à l’heure. »',\n    ],\n    clue: '« Nino l’a emportée au moulin pour la garder au sec », dit Léa. Pico remet son ruban et vous guide jusque-là.',\n    correct: 1,\n  },\n];\n\nexport function greyRabbitStory() {\n  const b = exampleBuilder('grey-rabbit', 'Histoire à choix multiples — Le lapin gris',\n    'Aide Pico à retrouver sa clochette avant la fête : trois pistes, des essais et deux dénouements au moulin.');\n  const { hub, returnAction } = opening(b, 'Le lapin gris',\n    'Choisis une piste avec la roue pour aider Pico à retrouver sa clochette.', 3500, {\n      introText: 'Pico, le lapin gris, doit ouvrir la fête avec sa clochette. Elle a disparu ! Tu l’aides à la retrouver avant le soir.',\n    });\n  const trails = [];\n  const clues = [];\n  RABBIT_TRAILS.forEach((trail, index) => {\n    const y = 500 + index * 980;\n    const start = b.stage(trail.title, 1280, y, { role: 'choice', image: true });\n    const scene = b.stage(trail.scene, 1920, y);\n    trails.push(start);\n    b.link(start, scene, `Commencer la piste ${trail.label}`, 1600, y);\n    const choices = [];\n    const outcomes = [];\n    trail.choices.forEach((name, rank) => {\n      const lane = y + (rank === 0 ? -200 : 200);\n      const choice = b.stage(name, 3200, lane, { role: 'choice', image: true });\n      const outcome = b.stage(trail.outcomes[rank], 3840, lane);\n      choices.push(choice);\n      outcomes.push(outcome);\n      b.link(choice, outcome, `Explorer la piste ${trail.label} : ${name}`, 3520, lane);\n    });\n    const choose = b.action(`Choisir la recherche sur la piste ${trail.label}`, choices, 2560, y);\n    b.transition(scene, choose);\n    const clue = b.stage(trail.clue, 4480, y);\n    const good = trail.correct ?? 0;\n    b.link(outcomes[good], clue, `Suivre l’indice ${trail.label} jusqu’au moulin`, 4160, y + (good === 0 ? -200 : 200));\n    b.transition(outcomes[1 - good], choose);\n    clues.push(clue);\n  });\n  const menu = b.action('Choisir une piste pour retrouver la clochette de Pico', trails, 960, 0);\n  b.transition(hub, menu);\n  const meeting = b.stage('Au moulin, une clochette tinte derrière la fenêtre. Pico se dresse sur ses pattes : « C’est la mienne ! »', 5120, 1480);\n  const meet = b.action('Réunir les trois pistes devant le moulin de Nino', [meeting], 4800, 1480);\n  clues.forEach((clue) => b.transition(clue, meet));\n  const inspect = b.stage('Nino l’a suspendue au loquet pour que son propriétaire la voie. La fenêtre est entrouverte, juste au-dessus de la cour.', 5760, 1480, { image: true });\n  b.link(meeting, inspect, 'Repérer la clochette suspendue au loquet', 5440, 1480);\n  const prompt = b.stage('La fenêtre est basse, mais la porte du moulin est fermée. Pico veut sa clochette. Comment peux-tu l’aider ?', 6400, 1480);\n  b.link(inspect, prompt, 'Chercher un moyen de rendre la clochette à Pico', 6080, 1480);\n  const names = ['Appeler Nino.', 'Passer une branche par l’ouverture.', 'Essayer la porte du moulin.'];\n  const results = [\n    'Nino arrive, souriant. « Je l’ai trouvée près du pont ! » Il ouvre la fenêtre et rend la clochette à Pico.',\n    'Tu passes une branche par l’ouverture. Pico te guide ; la clochette glisse jusqu’au bout du bois. Il la récupère !',\n    'La poignée tourne, mais la porte est verrouillée. Pico regarde la fenêtre : « Il nous faut un autre moyen. »',\n  ];\n  const choices = [];\n  const outcomes = [];\n  names.forEach((name, index) => {\n    const y = 1480 + (index - 1) * 360;\n    const choice = b.stage(name, 7680, y, { role: 'choice', image: true });\n    const outcome = b.stage(results[index], 8320, y);\n    choices.push(choice);\n    outcomes.push(outcome);\n    b.link(choice, outcome, `Récupérer la clochette de Pico : ${name}`, 8000, y);\n  });\n  const rescue = b.action('Choisir comment décrocher la clochette au moulin', choices, 7040, 1480);\n  b.transition(prompt, rescue);\n  b.transition(outcomes[2], rescue);\n  const endings = [\n    b.stage('Pour le remercier, Pico invite Nino à la fête. Le meunier ouvre le bal à ses côtés, au son de la clochette. Appuie sur OK pour rejouer.', 8960, 1120, { image: true, controls: { autoplay: false } }),\n    b.stage('Pico file à la fête avec toi. Il fait tinter sa clochette, et tous ses amis accourent en riant pour danser. Appuie sur OK pour rejouer.', 8960, 1480, { image: true, controls: { autoplay: false } }),\n  ];\n  endings.forEach((ending, index) => {\n    b.link(outcomes[index], ending, index === 0 ? 'Inviter Nino à la fête de Pico' : 'Ouvrir la fête avec la clochette retrouvée', 8640, 1120 + index * 360);\n    b.transition(ending, returnAction);\n  });\n  return b.finish(hub, returnAction);\n}\n\nconst LIGHTHOUSE_ROUTES = [\n  {\n    label: 'la plage', title: 'Passer par la plage.',\n    scene: 'Sur le sentier au-dessus de la plage, Nora trouve une corde près d’un abri. « Elle pourrait servir ! » Faut-il la prendre ?',\n    choices: ['Prendre la corde.', 'Laisser la corde à l’abri.'],\n    results: [\n      'Nora roule la corde et la porte jusqu’au phare. Luc l’attend devant la trappe du cellier, gonflée par l’humidité.',\n      'Nora range la corde à l’abri, puis rejoint Luc au phare. Il tente d’ouvrir une trappe gonflée par l’humidité.',\n    ],\n    problem: 'La trappe du cellier coince. Luc doit y prendre ses outils. Nora lui montre la corde : « On essaie de tirer ? »',\n    withoutRope: 'La trappe du cellier coince. Sans corde, Nora peut aider Luc à la soulever. Ses outils sont juste derrière.',\n    solutions: ['Tirer la trappe avec la corde.', 'Soulever la trappe avec Luc.'],\n    consequences: [\n      'Luc noue la corde à la poignée. Nora tire avec lui ; la trappe s’ouvre. Les outils retrouvés, ils montent vers la lampe.',\n      'Nora tient la trappe pendant que Luc la soulève. Les outils retrouvés, ils montent ensemble vers la lampe.',\n    ],\n  },\n  {\n    label: 'la forêt', title: 'Passer par la forêt.',\n    scene: 'Sous les pins, un panneau indique le phare. Inès, la forestière, propose un raccourci par la clairière.',\n    choices: ['Suivre le sentier balisé.', 'Prendre le raccourci d’Inès.'],\n    results: [\n      'Nora suit les marques bleues sur les arbres. Au dernier virage, la tour du phare surgit au-dessus des pins.',\n      'Inès accompagne Nora dans la clairière. Elles débouchent devant le phare. « Bon courage ! » lance la forestière.',\n    ],\n    problem: 'Au phare, Luc tâtonne dans l’escalier. Un volet est fermé ; sa lanterne attend sur une étagère. Comment éclairer les marches ?',\n    solutions: ['Prendre la lanterne de Luc.', 'Ouvrir le volet de l’escalier.'],\n    consequences: [\n      'Nora allume la lanterne que Luc lui tend. Il porte les outils ; elle éclaire chaque marche jusqu’à la lampe.',\n      'Le jour pâle entre par le volet. Nora voit les marches et monte derrière Luc, qui porte les outils.',\n    ],\n  },\n  {\n    label: 'le port', title: 'Passer par le port.',\n    scene: 'Au port, Sami amarre sa barque. Le phare est tout près, de l’autre côté de l’anse. Une passerelle longe les bateaux.',\n    choices: ['Traverser avec Sami.', 'Longer la passerelle.'],\n    results: [\n      'Sami rame près du rivage et dépose Nora au phare. « J’attendrai le faisceau pour sortir du port », lui dit-il.',\n      'La passerelle mène Nora au phare. Elle aperçoit le bateau de sa mère, immobile au large, et presse le pas.',\n    ],\n    problem: 'Luc pose son escabeau devant la lampe. Nora lui apporte l’ampoule neuve. Quel coup de main peut-elle lui donner ?',\n    solutions: ['Lui tendre l’ampoule.', 'Tenir son escabeau.'],\n    consequences: [\n      'Nora sort l’ampoule de sa boîte et la tend à Luc. Il remercie sa jeune assistante et se tourne vers la lampe.',\n      'Nora tient l’escabeau pendant que Luc monte. Il prend l’ampoule dans sa boîte, prêt à la poser.',\n    ],\n  },\n];\n\nexport function lighthouseStory() {\n  const b = exampleBuilder('lighthouse', 'Histoire à choix multiples — Le phare',\n    'Accompagne Nora jusqu’au phare : trois chemins, deux décisions et des conséquences qui suivent chaque trajet.');\n  const { hub, returnAction } = opening(b, 'Le phare de l’île aux brumes',\n    'Par quel chemin Nora va-t-elle au phare ? Choisis avec la roue.', 4300, {\n      introText: 'Le phare s’est éteint. Nora apporte une ampoule au gardien Luc : le bateau de sa mère attend dans la brume. Tu l’accompagnes.',\n    });\n  const paths = [];\n  const rescued = [];\n  LIGHTHOUSE_ROUTES.forEach((route, index) => {\n    const y = 600 + index * 1300;\n    const path = b.stage(route.title, 1280, y, { role: 'choice', image: true });\n    const scene = b.stage(route.scene, 1920, y);\n    paths.push(path);\n    b.link(path, scene, `Commencer le trajet par ${route.label}`, 1600, y);\n    const choices = [];\n    const results = [];\n    route.choices.forEach((name, rank) => {\n      const lane = y + (rank === 0 ? -230 : 230);\n      const choice = b.stage(name, 3200, lane, { role: 'choice', image: true });\n      const result = b.stage(route.results[rank], 3840, lane);\n      choices.push(choice);\n      results.push(result);\n      b.link(choice, result, `Poursuivre le trajet par ${route.label} : ${name}`, 3520, lane);\n    });\n    const choose = b.action(`Choisir le trajet de Nora par ${route.label}`, choices, 2560, y);\n    b.transition(scene, choose);\n    // La corde reste attachée au chemin qui la ramasse : le trajet sans corde\n    // possède sa propre scène et n'offre jamais une solution qui l'utiliserait.\n    const problems = index === 0 ? results.map((_, rank) => b.stage(rank === 0 ? route.problem : route.withoutRope, 4480, y + (rank === 0 ? -230 : 230)))\n      : [b.stage(route.problem, 4480, y)];\n    if (index === 0) results.forEach((result, rank) => b.link(result, problems[rank], rank === 0 ? 'Examiner la trappe avec la corde de Nora' : 'Examiner la trappe sans corde', 4160, y + (rank === 0 ? -230 : 230)));\n    else {\n      const arrival = b.action(`Arriver par ${route.label} et aider Luc au phare`, problems, 4160, y);\n      results.forEach((result) => b.transition(result, arrival));\n    }\n    const solutions = [];\n    route.solutions.forEach((name, rank) => {\n      const lane = y + (rank === 0 ? -230 : 230);\n      const solution = b.stage(name, 5760, lane, { role: 'choice', image: true });\n      const consequence = b.stage(route.consequences[rank], 6400, lane);\n      solutions.push(solution);\n      rescued.push(consequence);\n      b.link(solution, consequence, `Aider Luc après ${route.label} : ${name}`, 6080, lane);\n    });\n    const solve = b.action(`Après ${route.label}, choisir le coup de main de Nora`, solutions, 5120, y - (index === 0 ? 230 : 0));\n    b.transition(problems[0], solve);\n    if (index === 0) {\n      const withoutRope = b.action('Sans corde, aider Luc à soulever la trappe', [solutions[1]], 5120, y + 230);\n      b.transition(problems[1], withoutRope);\n    }\n  });\n  const menu = b.action('Choisir le chemin de Nora vers le phare', paths, 960, 0);\n  b.transition(hub, menu);\n  const light = b.stage('Luc pose l’ampoule neuve et tourne le commutateur. Un large faisceau perce la brume. Nora pousse un cri de joie.', 7040, 1900, { image: true });\n  const meet = b.action('Réunir les chemins pour rallumer la lampe avec Luc', [light], 6720, 1900);\n  rescued.forEach((stage) => b.transition(stage, meet));\n  const boats = b.stage('Au large, la mère de Nora voit le signal. Son bateau et deux autres suivent le chenal jusqu’au port.', 7680, 1900, { image: true });\n  b.link(light, boats, 'Guider les bateaux dans le chenal éclairé', 7360, 1900);\n  const thanks = b.stage('De retour au quai, Nora retrouve sa mère. « Votre lumière nous a guidés ! » Appuie sur OK pour choisir un autre chemin.', 8320, 1900, { controls: { autoplay: false } });\n  b.link(boats, thanks, 'Retrouver la mère de Nora sur le quai', 8000, 1900);\n  b.transition(thanks, returnAction);\n  return b.finish(hub, returnAction);\n}\n",
  "src/store/advancedExamples/trainExample.js": "import { exampleBuilder, opening } from './exampleBuilder.js';\n\nconst STATIONS = [\n  {\n    label: 'des étoiles',\n    title: 'La station des étoiles.',\n    scene: 'Le ciel est clair. Pour guider le train vers le nord, quelle étoile semble presque immobile dans notre ciel ?',\n    choices: ['L’étoile polaire.', 'Une étoile filante.'],\n    outcomes: [\n      'Bravo ! L’étoile polaire indique le nord. Remonte dans le train : une autre station t’attend.',\n      'L’étoile filante ne brille qu’un instant. Cherche une étoile qui semble rester en place. Réécoute la question.',\n    ], quiz: true,\n  },\n  {\n    label: 'des nuages',\n    title: 'La station des nuages.',\n    scene: 'La pilote prépare sa montgolfière. Pour observer les nuages, préfères-tu monter avec elle ou rester au sol ?',\n    choices: ['Monter dans la nacelle.', 'Observer avec des jumelles.'],\n    outcomes: [\n      'La nacelle s’élève au-dessus des champs. Un nuage ressemble à une baleine ! De retour au sol, tu retrouves le train.',\n      'Dans tes jumelles, un nuage ressemble à un train ; le vent efface sa locomotive. Le vrai train t’attend pour la suite.',\n    ],\n  },\n  {\n    label: 'des abeilles',\n    title: 'La station des abeilles.',\n    scene: 'Ça bourdonne autour des fleurs ! Les abeilles récoltent leur nectar. En quoi le transforment-elles dans la ruche ?',\n    choices: ['De la farine.', 'Du miel.'],\n    outcomes: [\n      'La farine vient de grains que l’on moud. Cherche ce que les abeilles fabriquent dans leur ruche. Réessaie !',\n      'Bravo ! Les abeilles transforment le nectar en miel. Le train t’attend : choisis une autre station avec la roue.',\n    ], quiz: true, correct: 1,\n  },\n  {\n    label: 'de la rivière',\n    title: 'La station de la rivière.',\n    scene: 'Le petit pont est fermé. Une passeuse t’appelle depuis sa barque, et un sentier mène à un autre pont. Quel chemin préfères-tu ?',\n    choices: ['Traverser avec la passeuse.', 'Marcher jusqu’à l’autre pont.'],\n    outcomes: [\n      'La barque glisse entre les reflets des saules. La passeuse te montre un poisson argenté. Puis tu rejoins le train.',\n      'Sur l’autre pont, tu vois la rivière dessiner de grands virages entre les prés. La promenade te ramène au train.',\n    ],\n  },\n  {\n    label: 'des nombres',\n    title: 'La station des nombres.',\n    scene: 'Deux oiseaux se posent sur la barrière. Trois autres les rejoignent. Combien d’oiseaux sont perchés ensemble ?',\n    choices: ['Cinq oiseaux.', 'Quatre oiseaux.'],\n    outcomes: [\n      'Bravo ! Deux et trois font cinq. Tous les oiseaux sont là ; le train t’attend pour une autre station.',\n      'Pas tout à fait ! Compte deux oiseaux, puis continue avec les trois nouveaux : trois, quatre, cinq. Réécoute et réessaie.',\n    ], quiz: true,\n  },\n  {\n    label: 'du moulin',\n    title: 'La station du moulin.',\n    scene: 'Les ailes du moulin tournent. Le meunier prépare sa farine. Veux-tu porter du grain avec lui ou l’aider à surveiller le vent ?',\n    choices: ['Porter un petit sac de grain.', 'Observer le vent.'],\n    outcomes: [\n      'À deux, vous apportez le grain au moulin. Bientôt, une farine douce remplit le sac. Le train t’attend près du champ.',\n      'Le ruban du meunier flotte dans le vent. Tu lui indiques sa direction, et il règle les ailes. Puis tu retrouves le train.',\n    ],\n  },\n  {\n    label: 'des saisons',\n    title: 'La station des saisons.',\n    scene: 'Des feuilles jaunes et rousses tourbillonnent autour du train. À quelle saison beaucoup d’arbres prennent-ils ces couleurs ?',\n    choices: ['Au printemps.', 'En automne.'],\n    outcomes: [\n      'Au printemps, les nouvelles feuilles sont généralement vertes. Cherche la saison des feuilles dorées. Réessaie !',\n      'Bravo ! En automne, beaucoup de feuilles changent de couleur avant de tomber. Le train t’attend pour la suite.',\n    ], quiz: true, correct: 1,\n  },\n  {\n    label: 'des lanternes',\n    title: 'La station des lanternes.',\n    scene: 'À la fête des lanternes, la fabricante te propose deux lumières pour la promenade. Laquelle préfères-tu ?',\n    choices: ['La lanterne lune.', 'La lanterne renard.'],\n    outcomes: [\n      'La lanterne lune pose des ronds de lumière sur le chemin. Tu traverses la fête comme un petit astronaute, puis rejoins le train.',\n      'La lanterne renard éclaire les rubans de la fête. Son ombre semble danser sur les murs ! Le train t’attend après la promenade.',\n    ],\n  },\n  {\n    label: 'des sons',\n    title: 'La station des sons.',\n    scene: 'Boum, boum ! La musicienne frappe une peau tendue pour faire résonner son instrument. De quel instrument s’agit-il ?',\n    choices: ['Le tambour.', 'La flûte.'],\n    outcomes: [\n      'Bravo ! La peau du tambour vibre quand on la frappe. Remonte dans le train et choisis ta prochaine station.',\n      'Dans une flûte, c’est le souffle qui produit le son. Cherche l’instrument avec une peau tendue. Réécoute la question.',\n    ], quiz: true,\n  },\n  {\n    label: 'du verger',\n    title: 'La station du verger.',\n    scene: 'Sous les pommiers, le jardinier prépare un goûter pour les voyageurs. Préfères-tu remplir le panier ou laver les pommes ?',\n    choices: ['Remplir le panier de pommes.', 'Laver les pommes.'],\n    outcomes: [\n      'Le jardinier cueille les pommes, et tu les ranges dans le panier. Le goûter sera croquant ! Puis tu retrouves le train.',\n      'Vous faites rouler les pommes dans l’eau : leur peau brille ! Le goûter est prêt, et le train t’attend pour la suite.',\n    ],\n  },\n];\n\nexport function explorerTrain() {\n  const b = exampleBuilder('explorer-train', 'Quiz et aventures — Train des explorateurs',\n    'Une grande roue de dix stations et une sortie, cinq mini-quiz et cinq aventures : chaque visite ramène au train.');\n  const { hub, returnAction } = opening(b, 'Le train des explorateurs.', 'Tchou, tchou ! Avec la roue, choisis une station, ou rentre à la gare.', 8400, {\n    introText: 'En voiture ! Avec la roue et OK, choisis une station, puis une réponse ou une aventure. Chaque visite te ramène au train. Prêt à partir ?',\n  });\n  const stops = [];\n  const completed = [];\n  STATIONS.forEach((station, index) => {\n    // Les défis et les aventures alternent, dans l'ordre de la roue.\n    // Chaque station garde sa bande et ses deux voies de décision.\n    const y = 450 + index * 780;\n    const stop = b.stage(station.title, 1280, y, { role: 'choice', image: true });\n    const scene = b.stage(station.scene, 1920, y);\n    stops.push(stop);\n    b.link(stop, scene, `Découvrir la station ${station.label}`, 1600, y);\n    const choices = [];\n    const outcomes = [];\n    station.choices.forEach((name, rank) => {\n      const lane = y + (rank === 0 ? -200 : 200);\n      const choice = b.stage(name, 3200, lane, { role: 'choice', image: true });\n      const outcome = b.stage(station.outcomes[rank], 3840, lane);\n      choices.push(choice);\n      outcomes.push(outcome);\n      b.link(choice, outcome, `Station ${station.label} — ${name}`, 3520, lane);\n    });\n    const choose = b.action(station.quiz ? `Réponses à la station ${station.label}` : `Aventures à la station ${station.label}`, choices, 2560, y);\n    b.transition(scene, choose);\n    if (station.quiz) {\n      const correct = station.correct ?? 0;\n      completed.push(outcomes[correct]);\n      b.link(outcomes[1 - correct], scene, `Réécouter le défi de la station ${station.label}`, 4160, y + (correct === 0 ? 200 : -200));\n    } else completed.push(...outcomes);\n  });\n  const exit = b.stage('Rentrer à la gare.', 1280, 8250, { role: 'choice', image: true });\n  const farewell = b.stage('Le train rentre doucement à la gare. Merci pour cette promenade ! Appuie sur OK pour retrouver les stations.',\n    1920, 8250, { image: true, controls: { autoplay: false } });\n  b.link(exit, farewell, 'Rentrer à la gare après le voyage', 1600, 8250);\n  b.transition(farewell, returnAction);\n  const wheel = b.action('Choisir parmi les dix stations ou rentrer à la gare', [...stops, exit], 960, 0);\n  b.transition(hub, wheel);\n  completed.forEach((outcome) => b.transition(outcome, wheel));\n  return b.finish(hub, returnAction);\n}\n",
  "src/store/advancedExamples/transaction.js": "import { advancedGestures, presence } from '../projectModel/advancedGestures.js';\nimport { isFallbackProjectName } from '../projectSaveName.js';\n\nconst withoutValue = (field) => field?.presence !== 'value';\nconst SHORT_MIN = -32768;\nconst SHORT_MAX = 32767;\nconst BLOCK_MARGIN = 400;\n\nfunction bounds(points) {\n  return {\n    minX: Math.min(...points.map((p) => p.x)), maxX: Math.max(...points.map((p) => p.x)),\n    minY: Math.min(...points.map((p) => p.y)), maxY: Math.max(...points.map((p) => p.y)),\n  };\n}\n\n// Le rectangle complet de l'exemple se place hors du rectangle du travail\n// existant. La géométrie intérieure reste intacte, y compris au bord short.\nexport function exampleInsertionAnchor(view, example, preferredPoint = { x: 0, y: 0 }) {\n  const offsets = [...example.stages, ...example.actions].map((node) => node.offset);\n  if (offsets.length === 0 || offsets.some((p) => !Number.isFinite(p?.x) || !Number.isFinite(p?.y))) {\n    throw new TypeError('Positions d’exemple invalides.');\n  }\n  const block = bounds(offsets);\n  const lowX = SHORT_MIN - block.minX;\n  const highX = SHORT_MAX - block.maxX;\n  const lowY = SHORT_MIN - block.minY;\n  const highY = SHORT_MAX - block.maxY;\n  const occupied = [...(view.stages ?? []), ...(view.actions ?? [])]\n    .map((node) => node.layout)\n    .filter((p) => Number.isFinite(p?.x) && Number.isFinite(p?.y));\n  const existing = occupied.length ? bounds(occupied) : null;\n  const free = (point) => Number.isFinite(point?.x) && Number.isFinite(point?.y)\n    && point.x >= lowX && point.x <= highX && point.y >= lowY && point.y <= highY\n    && (!existing\n      || point.x + block.minX >= existing.maxX + BLOCK_MARGIN\n      || point.x + block.maxX <= existing.minX - BLOCK_MARGIN\n      || point.y + block.minY >= existing.maxY + BLOCK_MARGIN\n      || point.y + block.maxY <= existing.minY - BLOCK_MARGIN);\n  if (free(preferredPoint)) return { x: preferredPoint.x, y: preferredPoint.y };\n  const alignX = Math.max(lowX, Math.min(highX, (existing?.minX ?? 0) - block.minX));\n  const alignY = Math.max(lowY, Math.min(highY, (existing?.minY ?? 0) - block.minY));\n  const candidates = existing ? [\n    { x: existing.maxX + BLOCK_MARGIN - block.minX, y: alignY },\n    { x: alignX, y: existing.maxY + BLOCK_MARGIN - block.minY },\n    { x: existing.minX - BLOCK_MARGIN - block.maxX, y: alignY },\n    { x: alignX, y: existing.minY - BLOCK_MARGIN - block.maxY },\n  ] : [{ x: alignX, y: alignY }];\n  const available = candidates.find(free);\n  if (available) return available;\n  throw Object.assign(new Error('Pas assez de place pour insérer cet exemple sans déplacer le graphe. Libère de l’espace puis réessaie.'), { code: 'EXAMPLE_POSITION_UNAVAILABLE' });\n}\n\n// Le squelette d'un projet neuf, tel que `create_advanced_document` le pose :\n// « Écran 1 », OK seul actif, aucun média ni raccord.\nconst SKELETON_NAME = 'Écran 1';\nconst SKELETON_CONTROLS = Object.freeze({ wheel: false, ok: true, home: false, pause: false, autoplay: false });\n\nfunction hasSkeletonControls(controls) {\n  return Object.entries(SKELETON_CONTROLS).every(([key, value]) => (\n    controls?.[key]?.presence === 'value' && controls[key].value === value\n  ));\n}\n\n// Seule une entrée encore **intacte** est un squelette remplaçable. Un nom\n// donné par l'auteur, un bouton réglé, une couleur, un média ou un raccord\n// sont du travail : l'exemple s'ajoute alors à côté au lieu de le supprimer.\nexport function initialRootUuid(view) {\n  if (view?.stages?.length !== 1 || (view.actions?.length ?? 0) !== 0) return null;\n  const stage = view.stages[0];\n  if (stage.squareOne?.presence !== 'value' || stage.squareOne.value !== true\n    || stage.uniqueId === false || !stage.uuid\n    || stage.name?.presence !== 'value' || String(stage.name.value ?? '').trim() !== SKELETON_NAME\n    || !hasSkeletonControls(stage.controls) || stage.personalColor\n    || !withoutValue(stage.audio) || !withoutValue(stage.image)\n    || !withoutValue(stage.okTransition) || !withoutValue(stage.homeTransition)) return null;\n  return stage.uuid;\n}\n\nexport function exampleSubgraph(example, anchor = { x: 0, y: 0 }) {\n  if (!Number.isFinite(anchor.x) || !Number.isFinite(anchor.y)) throw new TypeError('Position d’exemple invalide.');\n  if (!Number.isInteger(example.entryRank) || !example.stages?.[example.entryRank]) {\n    throw new TypeError('L’exemple doit désigner son Écran d’entrée.');\n  }\n  const position = (offset) => {\n    if (!Number.isFinite(offset?.x) || !Number.isFinite(offset?.y)) throw new TypeError('Position de nœud invalide.');\n    return { x: anchor.x + offset.x, y: anchor.y + offset.y };\n  };\n  return {\n    stages: example.stages.map(({ name, controls, offset }) => ({\n      name, controls: { ...controls }, audio: null, image: null, position: position(offset),\n    })),\n    actions: example.actions.map(({ name, options, offset }) => ({\n      name, options: options.map((option) => ({ ...option })), position: position(offset),\n    })),\n    transitions: example.transitions.map((transition) => ({ ...transition })),\n  };\n}\n\n// Les étapes produisent uniquement des valeurs locales. La session d'auteur\n// installe la **structure** complète en un seul commit — une seule étape\n// d'undo —, ou jette tout au refus et à la péremption (undo, autre projet).\n// Les médias ne font pas partie de cette transaction : ils arrivent ensuite,\n// par des gestes séparés que `useAdvancedExamples` fond dans cette même étape\n// tant que l'auteur n'a rien fait d'autre (voir `exampleHistory.js`).\nexport async function prepareExampleInsertion(project, example, {\n  applyGesture, readView, isCurrent = () => true, anchor = { x: 0, y: 0 },\n}) {\n  const assertCurrent = () => {\n    if (!isCurrent()) throw new Error('Le document de cet exemple a changé.');\n  };\n  assertCurrent();\n  const view = await readView(project);\n  assertCurrent();\n  const rootUuid = initialRootUuid(view);\n  const placedAnchor = rootUuid ? { x: 0, y: 0 } : exampleInsertionAnchor(view, example, anchor);\n  let result = await applyGesture(project, advancedGestures.pasteSubgraph(exampleSubgraph(example, placedAnchor)));\n  assertCurrent();\n  const construction = result.report?.construction;\n  if (construction?.stages?.length !== example.stages.length\n    || construction?.actions?.length !== example.actions.length) {\n    throw new Error('Le collage n’a pas rendu les identifiants des nœuds créés.');\n  }\n  const entryUuid = construction.stages[example.entryRank];\n  if (rootUuid) {\n    result = await applyGesture(result.project, advancedGestures.setSquareOne(entryUuid));\n    assertCurrent();\n    result = await applyGesture(result.project, advancedGestures.deleteStage(rootUuid));\n    assertCurrent();\n    const documentTitle = view.metadata?.title?.presence === 'value'\n      ? String(view.metadata.title.value ?? '').trim() : '';\n    const titleIsFallback = !documentTitle || documentTitle.normalize('NFKC').toLowerCase() === 'nouveau pack';\n    if (titleIsFallback) {\n      result = await applyGesture(result.project, advancedGestures.setDocumentMetadata({\n        title: presence.value(example.title),\n      }));\n      assertCurrent();\n    }\n    if (isFallbackProjectName(result.project.projectName)) {\n      result = { ...result, project: { ...result.project, projectName: titleIsFallback ? example.title : documentTitle } };\n    }\n  }\n  return {\n    project: result.project,\n    report: {\n      ...result.report,\n      example: {\n        id: example.id, stages: [...construction.stages], actions: [...construction.actions],\n        entryUuid, replacedInitialRoot: rootUuid !== null, anchor: placedAnchor,\n      },\n    },\n  };\n}\n"
};
